package dev.almaz.pathway.service;
import org.springframework.ai.chat.client.ChatClient;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;
@Service public class AiService { private final ChatClient chat; @Value("${AI_API_KEY:}") private String key; public AiService(ChatClient.Builder builder){this.chat=builder.build();} public String analyze(String mode,String language,String input){if(key==null||key.isBlank())throw new IllegalStateException("Configure AI_API_KEY on the backend to enable LLM analysis.");String system="You are a careful software engineering assistant. Provide practical, security-aware guidance. Do not claim to execute code. Return concise markdown with findings and suggested changes.";return chat.prompt().system(system).user(u->u.text("Mode: {mode}\\nLanguage: {language}\\nInput:\\n{input}").param("mode",mode).param("language",language).param("input",input)).call().content();} }
